{email_header}
<p>Hello, {profile_name}.</p>
<p><b><a href="{viewer_url}">{viewer_name}</a></b> is a client of your business <b><a href="{listing_url}">{listing_name}</a></b>.</p>
{email_footer}

{email_header}
<p>Hello, {profile_name}.</p>
<p>Your claim for the business <b><a href="{listing_url}">{listing_name}</a></b> has been accepted by the Site Administrators. You are now able to manage the listing.</p>
{email_footer}

{email_header}
<p>Hello, {profile_name}.</p>
<p>Sorry, your claim for the business <b><a href="{listing_url}">{listing_name}</a></b> has been rejected by the Site Administrators.</p>
{email_footer}

{email_header}
<p>Hello Administrator,</p>
<p>A Claim request has been submitted for <b><a href="{listing_url}">{listing_name}</a></b>. You may manage the request <a href="{manage_url}">here</a></b>.</p>
{email_footer}
